SELECT CAST(rowid AS TEXT) AS legacy_rowid,CAST(CASE WHEN typeof(attempt)='text' THEN attempt END AS TEXT) AS attempt,CAST(CASE WHEN typeof(operation)='text' THEN operation END AS TEXT) AS operation,CAST(CASE WHEN typeof(request)='text' THEN request END AS TEXT) AS request,CAST(CASE WHEN typeof(requested_by)='text' THEN requested_by END AS TEXT) AS requested_by,CAST(CASE WHEN typeof(admitted_at)='text' THEN admitted_at END AS TEXT) AS admitted_at,CAST(CASE WHEN typeof(target_schema)='text' THEN target_schema END AS TEXT) AS target_schema,CAST(CASE WHEN typeof(follow_up)='text' THEN follow_up END AS TEXT) AS follow_up FROM _fleet_sync_transfer_admissions
